import axios from 'axios';

/**
 * Custom HTTP client built on Axios with built-in token management, 401 retry, telemetry events, and caching.
 */
export class HttpClient {
  constructor(baseUrl, authManager, options = {}) {
    this.authManager = authManager;
    this.logger = options.logger || null;
    
    // Telemetry / event listeners
    this.listeners = {
      request: [],
      response: [],
      error: [],
    };

    // Simple in-memory GET cache map
    this.cacheStore = new Map();
    
    const allowedMethods = options.retryMethods || options.retryConfig?.allowedMethods || ['get', 'head', 'options', 'put', 'delete'];

    this.retryConfig = {
      retries: options.retries ?? 0,
      retryDelay: options.retryDelay ?? 1000,
      allowedMethods: allowedMethods.map(m => m.toLowerCase()),
      ...options.retryConfig
    };
    
    this.client = axios.create({
      baseURL: baseUrl,
      headers: {
        'Content-Type': 'application/json',
      },
      ...(options.axiosConfig || {})
    });

    this.setupInterceptors();
  }

  // --- Telemetry Event Registration ---

  onRequest(fn) {
    if (typeof fn === 'function') this.listeners.request.push(fn);
    return this;
  }

  onResponse(fn) {
    if (typeof fn === 'function') this.listeners.response.push(fn);
    return this;
  }

  onError(fn) {
    if (typeof fn === 'function') this.listeners.error.push(fn);
    return this;
  }

  // --- In-Memory Cache Helpers ---

  getCache(key) {
    const entry = this.cacheStore.get(key);
    if (!entry) return null;
    if (Date.now() > entry.expiresAt) {
      this.cacheStore.delete(key);
      return null;
    }
    return entry.value;
  }

  setCache(key, value, ttlMs) {
    this.cacheStore.set(key, {
      value,
      expiresAt: Date.now() + ttlMs,
    });
  }

  clearCache() {
    this.cacheStore.clear();
  }

  /**
   * Registers a global middleware (interceptor).
   */
  use({ request, response }) {
    if (request) this.client.interceptors.request.use(request);
    if (response) this.client.interceptors.response.use(response);
  }

  setupInterceptors() {
    // Request Interceptor: Inject Authorization header & notify listeners
    this.client.interceptors.request.use(
      async (config) => {
        const token = await this.authManager.getToken();
        if (token) {
          config.headers = config.headers || {};
          const hasAuthHeader = Object.keys(config.headers).some(h => h.toLowerCase() === 'authorization');
          if (!hasAuthHeader) {
            config.headers['Authorization'] = `Bearer ${token}`;
          }
        }

        // Notify request listeners
        this.listeners.request.forEach(fn => {
          try { fn(config); } catch (e) { /* ignore listener errors */ }
        });

        return config;
      },
      (error) => Promise.reject(error)
    );

    // Response Interceptor: Handle 401, Generic Retry, and Telemetry
    this.client.interceptors.response.use(
      (response) => {
        // Notify response listeners
        this.listeners.response.forEach(fn => {
          try { fn(response); } catch (e) { /* ignore listener errors */ }
        });
        return response;
      },
      async (error) => {
        const { config, response } = error;

        // Notify error listeners
        this.listeners.error.forEach(fn => {
          try { fn(error, config); } catch (e) { /* ignore listener errors */ }
        });

        if (!config) return Promise.reject(error);
        
        // 1. Handle 401 Unauthorized (AuthManager handles the queue)
        if (response?.status === 401 && !config._retry) {
          config._retry = true;
          try {
            const newToken = await this.authManager.refreshToken();
            config.headers = config.headers || {};
            config.headers['Authorization'] = `Bearer ${newToken}`;
            return this.client(config);
          } catch (refreshError) {
            return Promise.reject(refreshError);
          }
        }

        // 2. Handle Generic Retry (5xx or Network errors for idempotent methods)
        const method = (config.method || 'get').toLowerCase();
        const isAllowedMethod = this.retryConfig.allowedMethods.includes(method);
        const isServerOrNetworkError = !response || response.status >= 500;
        const currentRetryCount = config._retryCount || 0;

        const shouldRetry = (this.retryConfig.retries > 0) && 
                           isAllowedMethod &&
                           isServerOrNetworkError &&
                           (currentRetryCount < this.retryConfig.retries);

        if (shouldRetry) {
          config._retryCount = currentRetryCount + 1;
          const delay = Math.pow(2, config._retryCount - 1) * this.retryConfig.retryDelay;
          
          if (typeof this.logger === 'function') {
            this.logger(`[fluent-rest-client] Retrying (${config._retryCount}/${this.retryConfig.retries}) ${config.method.toUpperCase()} ${config.url} in ${delay}ms`);
          }
          
          await new Promise(resolve => setTimeout(resolve, delay));
          return this.client(config);
        }

        return Promise.reject(error);
      }
    );
  }

  // Basic HTTP methods wrapper
  async request(config) {
    return this.client.request(config);
  }
}


